#include <iostream>
#include <queue>
#include <utility>
#include <vector>
using namespace std;

using ll = long long;
#define rep(i, n) for (int i = 0; i < (n); i++)

struct E {
  int u, v, cost;
};
vector<vector<E>> g;

vector<ll> dijkstra(int start = 0) {
  int N = g.size();
  vector<ll> d(N, 1e18);
  using P = pair<ll, int>;
  priority_queue<P, vector<P>, greater<P>> Q;

  Q.emplace(0, start);
  d[start] = 0;

  while (!Q.empty()) {
    auto [dc, c] = Q.top();
    Q.pop();
    if (d[c] != dc) continue;
    for (auto& e : g[c]) {
      ll dist = dc + e.cost;
      if (dist < d[e.v]) {
        d[e.v] = dist;
        Q.emplace(dist, e.v);
      }
    }
  }

  return d;
}

int main() {
  int N;
  cin >> N;
  g.resize(N);
  rep(i, N - 1) {
    int a, b, c;
    cin >> a >> b >> c;
    --a, --b;
    g[a].push_back(E{a, b, c});
    g[b].push_back(E{b, a, c});
  }
  vector<ll> D(N);
  for (auto& x : D) cin >> x;

  // 直径を求める
  int s = 0, t = -1, u = -1;

  {
    auto ds = dijkstra(s);
    // 最遠点は？
    ll cost = -1;
    rep(i, N) {
      if (i == s) continue;
      if (D[i] + ds[i] > cost) {
        cost = D[i] + ds[i];
        t = i;
      }
    }
  }

  {
    auto dt = dijkstra(t);
    // 最遠点は？
    ll cost = -1;
    rep(i, N) {
      if (i == t) continue;
      if (D[i] + dt[i] > cost) {
        cost = D[i] + dt[i];
        u = i;
      }
    }
  }

  // t, u が間の距離が直径に
  auto dt = dijkstra(t);
  auto du = dijkstra(u);
  rep(i, N) {
    ll cost = -1;
    if (i != t) cost = max(cost, dt[i] + D[t]);
    if (i != u) cost = max(cost, du[i] + D[u]);
    cout << cost << "\n";
  }
}

#include <iostream>
#include <vector>
using namespace std;

template <typename Cost>
struct Edge {
  int src, to;
  Cost cost;
  Edge(int s, int t, Cost c = 1) : src(s), to(t), cost(c) {}
  operator int() const { return to; }
};
template <typename Cost>
struct Graph : vector<vector<Edge<Cost>>> {
  Graph(int n) : vector<vector<Edge<Cost>>>(n) {}
  void add_edge(int s, int t, Cost c = 1) { (*this)[s].emplace_back(s, t, c); }
};

template <typename Cost, typename Data, Data (*merge)(Data, Data), Data (*e)(),
          Data (*leaf)(), Data (*apply)(Data, int, int, Cost)>
struct Rerooting : Graph<Cost> {
  vector<Data> dp, memo;

  Rerooting(int n) : Graph<Cost>::Graph(n) {}

  vector<Data> run() {
    memo.resize((*this).size(), e());
    dp.resize((*this).size());
    dfs1(0, -1);
    dfs2(0, -1, e());
    return dp;
  }

  void dfs1(int c, int p) {
    bool upd = false;
    for (Edge<Cost> &d : (*this)[c]) {
      if (d == p) continue;
      dfs1(d, c);
      upd = true;
      memo[c] = merge(memo[c], apply(memo[d], d, c, d.cost));
    }
    if (!upd) memo[c] = leaf();
  }

  void dfs2(int c, int p, const Data &val) {
    vector<Data> ds{val};
    for (Edge<Cost> &d : (*this)[c]) {
      if (d == p) continue;
      ds.push_back(apply(memo[d], d, c, d.cost));
    }
    int n = ds.size(), idx = 1;
    vector<Data> head(n + 1, e()), tail(n + 1, e());
    for (int i = 0; i++ < n;) head[i] = merge(head[i - 1], ds[i - 1]);
    for (int i = n; i-- > 0;) tail[i] = merge(tail[i + 1], ds[i]);
    dp[c] = head[n];
    for (Edge<Cost> &d : (*this)[c]) {
      if (d == p) continue;
      Data sub = merge(head[idx], tail[idx + 1]);
      dfs2(d, c, apply(sub, c, d, d.cost));
      idx++;
    }
  }
};

vector<int> D;

using Data = long long;
using Cost = long long;
Data merge(Data a, Data b) { return max(a, b); }
Data e() { return 0; }
Data leaf() { return 0; }
Data apply(Data a, int c, int, Cost w) { return max<Data>(a, D[c]) + w; }

int main() {
  int N;
  cin >> N;
  Rerooting<Cost, Data, merge, e, leaf, apply> g(N);
  for (int i = 0; i < N - 1; i++) {
    int s, t, c;
    cin >> s >> t >> c;
    g.add_edge(s - 1, t - 1, c);
    g.add_edge(t - 1, s - 1, c);
  }
  D.resize(N);
  for (auto &x : D) cin >> x;
  auto ans = g.run();
  for (auto &x : ans) cout << x << "\n";
}
